import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";

const InvoiceIndex = () => {
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({
        buyerID: "",
        sellerID: "",
        product: "",
        minPrice: "",
        maxPrice: "",
        limit: "40"
    });
    const [buyerList, setBuyerList] = useState([]);
    const [sellerList, setSellerList] = useState([]);

    const deleteInvoice = async (id) => {
        try {
            await apiDelete("/api/invoices/" + id);
            setInvoices((prev) => prev.filter((item) => item.id !== id));
        } catch (error) {
            console.log(error.message);
            alert(error.message);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;

        setFilter((prev) => ({
            ...prev,
            [name]: value === "" ? null : value, // Pokud je prázdné, nastavíme na null
        }));
    };


    const handleFilterSubmit = async (e) => {
        e.preventDefault();

        const sanitizedFilter = Object.fromEntries(
            Object.entries(filter)
                .filter(([_, v]) => v !== "" && v !== null) // Odstranění prázdných hodnot
                .map(([key, value]) => [key, isNaN(value) ? value : Number(value)]) // Čísla převedu na Number
        );

        const queryParams = new URLSearchParams(sanitizedFilter).toString();
        const apiUrl = `/api/invoices${queryParams ? `?${queryParams}` : ""}`; // Správné sestavení URL

        console.log("🔎 Filtruji faktury s:", apiUrl);

        try {
            const response = await apiGet(apiUrl);
            console.log("✅ API odpověď:", response);
            setInvoices(response);
        } catch (error) {
            console.error("❌ Chyba při načítání faktur:", error);
        }
    };



    useEffect(() => {
        const fetchData = async () => {
            const invoicesData = await apiGet("/api/invoices");
            setInvoices(invoicesData);

            const personsData = await apiGet("/api/persons");
            setBuyerList(personsData);
            setSellerList(personsData);
        };

        fetchData();
    }, []);

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter
                filter={filter}
                handleChange={handleFilterChange}
                handleSubmit={handleFilterSubmit}
                confirm="Filtrovat"
                buyerList={buyerList}
                sellerList={sellerList}
            />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} label="Počet faktur:" />
        </div>
    );
};

export default InvoiceIndex;
